<template><div class="form-page"><el-form label-width="150px" label-position="left"><MetadataEditor :model="localForm" title="基础配置" /><el-card shadow="never"><template #header>DaemonSet 配置</template><div class="grid-three"><el-form-item label="更新策略"><el-select v-model="localForm.updateStrategy" placeholder="可不选"><el-option label="不指定" value="" /><el-option label="滚动更新" value="RollingUpdate" /><el-option label="删除时更新" value="OnDelete" /></el-select></el-form-item><el-form-item label="最大不可用数"><el-input v-model="localForm.maxUnavailable" /></el-form-item><el-form-item label="最小就绪秒数"><el-input-number v-model="localForm.minReadySeconds" :min="0" /></el-form-item></div><el-form-item label="选择器标签"><KeyValueEditor v-model="localForm.matchLabels" /></el-form-item></el-card><PodTemplateEditor :model="localForm.podTemplate" title="Pod 模板" /></el-form></div></template>
